const params=new URLSearchParams(location.search);if(params.has('embed'))document.documentElement.classList.add('embed');
const media=matchMedia('(prefers-color-scheme: dark)');let preference;try{preference=localStorage.getItem('techbuzzs-theme')||'system'}catch{preference='system'}
function applyTheme(value){const theme=value==='system'?(media.matches?'dark':'light'):value;document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-theme-button]').forEach(b=>{b.textContent=preference==='system'?'◐ System':theme==='dark'?'☾ Dark':'☀ Light'});window.dispatchEvent(new CustomEvent('themechange',{detail:theme}))}
applyTheme(params.get('theme')||preference);media.addEventListener('change',()=>{if(preference==='system'&&!params.has('theme'))applyTheme('system')});document.querySelectorAll('[data-theme-button]').forEach(b=>b.onclick=()=>{preference=preference==='system'?'light':preference==='light'?'dark':'system';try{localStorage.setItem('techbuzzs-theme',preference)}catch{}applyTheme(preference)});
window.addEventListener('message',e=>{if(e.origin!=='https://tech-buzzs-portfolio.vercel.app'&&e.origin!==location.origin&&!/^http:\/\/localhost:\d+$/.test(e.origin))return;if(e.data?.type==='techbuzzs-theme'&&['light','dark'].includes(e.data.theme))applyTheme(e.data.theme)});
export const $=s=>document.querySelector(s);export const $$=s=>[...document.querySelectorAll(s)];export function status(message,error=false){const e=$('#status');if(e){e.textContent=message;e.classList.toggle('error',error)}}
export function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
export function canvasBlob(canvas,type='image/png',quality=.9){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Could not export this image.')),type,quality))}
export function bytes(n){return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(2)+' MB'}
export function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}export async function copy(text){try{await navigator.clipboard.writeText(text);status('Copied to clipboard.')}catch{status('Clipboard unavailable. Select the text and copy it.',true)}}
